import {mediaUI} from './media.js';
import {guestUI} from './guest-booking.js';
import {readBookingDraft,saveBookingDraft,clearBookingDraft} from './booking-draft.js';
const $=(s,r=document)=>r.querySelector(s), app=$('#app'), modal=$('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const icons={search:'<circle cx="10.8" cy="10.8" r="6.5"/><path d="m16 16 4.5 4.5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',pin:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 13v8h14v-8"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',heart:'<path d="M20 5c-3-3-7-1-8 1-1-2-5-4-8-1s-1 7 8 15c9-8 11-12 8-15Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const media=mediaUI({esc,icon,money});
let feedCursor=null,resumeAfterRecovery=false;
const categories=['Все направления','Маникюр','Волосы','Брови и ресницы','Макияж','Косметология','Массаж'];
let me=null,myProfile=null,providers={},profiles=[],studio=null,appointments=[],library=null,category='',city='',search='',currentDate=new Date(),installPrompt=null,mapInstance=null;
let profileCalendarMonth=new Date(),profileCalendarDate='',profileCalendarSlug='',renderId=0;
async function api(url,options={}){let r;try{r=await fetch('/api'+url,{...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...options.headers}})}catch{throw Error('Нет соединения. Изменения не сохранены — попробуйте ещё раз после подключения.')}if(!r.headers.get('content-type')?.includes('application/json'))throw Error(r.status===413?'Фотографии слишком большие. Выберите до 6 файлов по 8 МБ.':'Сервис временно недоступен. Попробуйте позже.');const data=await r.json();if(!r.ok)throw Error(data.error||'Не удалось выполнить действие');return data}
const post=(url,body,method='POST')=>api(url,{method,body:JSON.stringify(body)});
const guest=guestUI({post,esc,icon,money,empty,getMe:()=>me});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
async function refreshMe(){const d=await api('/me');me=d.user;myProfile=d.profile;providers=d.providers}
async function route(path){history.pushState({},'',path);await render();window.scrollTo(0,0)}
function active(p){return location.pathname===p?'active':''}
function accountPath(){return me?.account_type==='master'?'/studio':'/me'}
function header(){return `<header class="header"><a class="brand" href="/" data-route><span class="brand-mark">a</span><span>ателье<span class="brand-sub">ПРОСТРАНСТВО МАСТЕРОВ</span></span></a><nav class="desktop-nav" aria-label="Главное меню"><a href="/" data-route class="${active('/')}">Мастера</a><a href="/inspiration" data-route class="${active('/inspiration')}">Вдохновение</a><a href="/map" data-route class="${active('/map')}">Карта</a></nav><div class="header-actions"><button class="icon-button" data-action="notifications" aria-label="Уведомления">${icon('bell')}</button>${me?`<a class="account" href="${accountPath()}" data-route>${icon('user')}<span>${me.account_type==='master'?'Студия':'Моё'}</span></a>`:`<button class="button small" data-action="auth">Войти ${icon('arrow')}</button>`}</div></header>`}
function nav(){const path=accountPath(),master=me?.account_type==='master';return `<nav class="bottom-nav" aria-label="Навигация"><a href="/" data-route class="${active('/')}">${icon('grid')}Мастера</a><a href="/inspiration" data-route class="${active('/inspiration')}">${icon('image')}Лента</a><a href="${me?'/calendar':'/map'}" data-route class="${active(me?'/calendar':'/map')}">${icon(me?'calendar':'pin')}${me?'Записи':'Карта'}</a><a href="${path}" data-route class="${active(path)}">${icon(master?'user':'heart')}${master?'Студия':'Моё'}</a></nav>`}
function footer(){return `<footer><span class="footer-brand">ателье</span><span>Красота начинается с человека.</span><button class="text-button" data-action="install">Установить приложение ${icon('arrow')}</button></footer>`}
function empty(title,text,button=''){return `<div class="empty"><span class="empty-symbol">✧</span><h3>${title}</h3><p>${text}</p>${button}</div>`}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function dialog(title,body,wide=false){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></div>${body}`;modal.className=wide?'wide':'';if(!modal.open)modal.showModal()}
function auth(mode='login',returnTo=location.pathname+location.hash,accountType='client'){const signup=mode==='register',recover=mode==='recover',roles=signup?`<fieldset class="role-switch"><legend>Как вы будете пользоваться Ателье?</legend><label><input type="radio" name="account_type" value="client" ${accountType!=='master'?'checked':''}><span>${icon('heart')}<strong>Я клиент</strong><small>Ищу мастеров и храню записи</small></span></label><label><input type="radio" name="account_type" value="master" ${accountType==='master'?'checked':''}><span>${icon('image')}<strong>Я мастер</strong><small>Показываю работы и веду запись</small></span></label></fieldset>`:'';dialog(signup?'Добро пожаловать в Ателье':recover?'Восстановить доступ':'С возвращением',`<p class="muted">${signup?'Выберите роль — она определит ваш личный кабинет.':recover?'Используйте код, который вы сохранили при регистрации.':'Сохраняйте работы, следите за мастерами и записывайтесь в одном месте.'}</p>${providers.yandex?'<a class="button secondary full" href="/auth/yandex">Войти через Яндекс</a><div class="divider">или</div>':''}<form data-form="auth" data-mode="${mode}" data-return="${esc(returnTo)}">${roles}${field('Логин','login','','text','required autocomplete="username" minlength="3" maxlength="32" pattern="[a-zA-Z0-9_-]+" placeholder="Например, anna-beauty"')}${recover?field('Код восстановления','recovery','','text','required autocomplete="off"'):''}${field(recover?'Новый пароль':'Пароль','password','','password',`required ${signup||recover?'minlength="10"':''} maxlength="128" autocomplete="${signup||recover?'new-password':'current-password'}"`)}${signup?'<p class="hint">Минимум 10 символов. После регистрации сохраните код восстановления доступа.</p>':''}<p class="form-error" role="alert"></p><button class="button full" type="submit">${signup?'Создать аккаунт':recover?'Восстановить':'Войти'} ${icon('arrow')}</button></form><div class="auth-links"><button class="text-button" data-action="auth-mode" data-mode="${signup?'login':'register'}" data-account="${accountType}">${signup?'Уже есть аккаунт':'Создать аккаунт'}</button>${!recover?'<button class="text-button" data-action="auth-mode" data-mode="recover">Забыли пароль?</button>':''}</div>`)}
function recoveryDialog(code){dialog('Сохраните код восстановления',`<p>Этот код нужен, если вы забудете пароль. Храните его в менеджере паролей. Мы не отправляем SMS.</p><code class="recovery">${esc(code)}</code><button class="button full" data-action="save-recovery" data-code="${esc(code)}">Скачать код</button><button class="text-button full" data-action="close">Я сохранил код</button>`)}
function filters(){return `<div class="filters"><div class="search-field">${icon('search')}<input id="search" aria-label="Поиск мастера" placeholder="Имя мастера или направление" value="${esc(search)}"></div><div class="city-field">${icon('pin')}<input id="city" aria-label="Город" placeholder="Вся Россия" value="${esc(city)}"></div><button class="button secondary" data-action="search">Найти</button></div><div class="chips" aria-label="Направления">${categories.map((c,i)=>`<button class="chip ${category===(i?c:'')?'selected':''}" data-action="category" data-value="${i?c:''}">${c}</button>`).join('')}</div>`}
function card(p){const cover=p.works[0]?.image;return `<a class="master-card ${esc(p.theme)}" href="/m/${esc(p.slug)}" data-route><div class="card-cover ${cover?'with-work':''}" ${cover?`style="background-image:linear-gradient(180deg,#10251b22,#10251bd9),url('${esc(cover)}')"`:''}><span class="tiny-label">${esc(p.category)}${p.is_demo?' · ПРИМЕР':''}</span><span class="cover-seal">a</span></div><div class="card-info"><div class="avatar">${p.avatar?`<img src="${esc(p.avatar)}" alt="" loading="lazy">`:esc(p.name.slice(0,1))}</div><h3>${esc(p.name)}</h3><p>${icon('pin')}${esc(p.city)}</p><div class="mini-works">${p.works.slice(0,3).map(w=>`<img src="${esc(w.image)}" alt="${esc(w.caption||'Работа мастера')}" loading="lazy">`).join('')}</div><div class="card-bottom"><span>${p.services.length?'от '+money(Math.min(...p.services.map(s=>s.price))):'Знакомство с мастером'}</span>${icon('arrow')}</div></div></a>`}
async function loadProfiles(){profiles=await api('/profiles?'+new URLSearchParams({category,city,q:search}));return profiles}
function profileResults(){return profiles.length?`<div class="master-grid">${profiles.map(card).join('')}</div>`:empty(city||category||search?'Пока нет подходящих мастеров':'Первая глава — ваша',city||category||search?'Попробуйте другое направление или соседний город.':'Ателье только открывается. Создайте свою страницу и пригласите клиентов по личной ссылке.',`<button class="button secondary" data-action="create">Создать страницу ${icon('plus')}</button>`)}
function bookingEntry(){return `<section class="booking-entry"><div><p class="eyebrow">БЕЗ ЛИШНИХ ШАГОВ</p><h2>Запись без регистрации</h2><p>Выберите мастера, услугу и время. Оставьте имя и контакт — мастер подтвердит запись.</p></div><a class="button" href="/book" data-route>Выбрать мастера ${icon('arrow')}</a></section>`}
async function bookingPage(){const available=(await api('/profiles')).filter(p=>!p.is_demo&&p.services.length);return `<a href="/" data-route class="back-link">← Все мастера</a><section class="page-intro"><div><p class="eyebrow">ВАШЕ ВРЕМЯ ДЛЯ СЕБЯ</p><h1>Запись <em>без регистрации.</em></h1></div><p class="intro-note">Откройте страницу мастера и нажмите «Записаться».<br>Понадобятся только имя и контакт для связи.</p></section>${available.length?`<div class="master-grid">${available.map(card).join('')}</div>`:empty('Мастера готовятся к знакомству','Здесь появятся мастера, которые опубликовали страницу и добавили услуги.','<a class="button secondary" href="/" data-route>Посмотреть портфолио</a>')}`}
function guestCalendar(){return `<section class="page-intro"><div><p class="eyebrow">ВАШ ДЕНЬ, В ВАШЕМ РИТМЕ</p><h1>Всё <em>по записи.</em></h1></div></section>${bookingEntry()}<section class="panel"><h2>Уже оставили заявку?</h2><p>Откройте личную ссылку, которую получили после записи. По ней можно проверить подтверждение мастера или отменить визит без входа.</p><p class="muted">Записи, сохранённые в аккаунт, история посещений и отзывы доступны после входа.</p><button class="button secondary" data-action="auth">Войти в мой аккаунт ${icon('arrow')}</button></section>`}
function studioBookings(){const start=new Date(currentDate);start.setDate(start.getDate()-((start.getDay()+6)%7));const days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return d});const list=appointments.filter(a=>dateKey(new Date(a.start))===dateKey(currentDate));const pending=appointments.filter(a=>a.master_id===me.id&&a.status==='pending');return `<div class="section-heading studio-schedule-heading" style="margin-top: 30px;"><h2>Расписание</h2><button class="button small" data-action="appointment">${icon('plus')} Новая запись</button></div><section class="panel" style="padding: 0; overflow: hidden; margin-bottom: 30px;"><div class="calendar-shell" style="border: none;"><div class="calendar-toolbar"><h2>${currentDate.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</h2><div class="action-row"><button class="button secondary small" data-action="today">Сегодня</button><button class="icon-button" data-action="week" data-delta="-7" aria-label="Предыдущая неделя">←</button><input class="date-jump" type="date" aria-label="Выбрать дату" id="date-jump" value="${dateKey(currentDate)}"><button class="icon-button" data-action="week" data-delta="7" aria-label="Следующая неделя">→</button></div></div><div class="week-strip">${days.map(d=>`<button class="day ${dateKey(d)===dateKey(currentDate)?'selected':''}" data-action="day" data-date="${dateKey(d)}"><span>${d.toLocaleDateString('ru-RU',{weekday:'short'})}</span><strong>${d.getDate()}</strong><span class="day-mark">${appointments.some(a=>a.status!=='cancelled'&&dateKey(new Date(a.start))===dateKey(d))?'•':' '}</span></button>`).join('')}</div><div class="day-agenda"><div class="section-heading"><h3>${currentDate.toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</h3><span class="muted">Часовой пояс: ${Intl.DateTimeFormat().resolvedOptions().timeZone}</span></div>${list.length?list.map(appointmentCard).join(''):empty('Время для новых планов','На этот день записей пока нет.')}</div></div></section>${pending.length?`<section class="panel" style="margin-bottom: 30px;"><h2>Новые заявки <span class="count">${pending.length}</span></h2><div class="compact-feed">${pending.map(appointmentCard).join('')}</div></section>`:''}`;}
function creatorBoard(p){const published=studio.works.filter(w=>w.pinned).length;return `<section class="panel compact-stats"><div class="stat-row"><div><strong>${studio.works.length}</strong><span>работ в портфолио</span></div><div><strong>${published}</strong><span>закреплено</span></div><div><strong>${appointments.filter(a=>a.master_id===me.id&&a.status==='pending').length}</strong><span>новых заявок</span></div></div><button class="button small" data-action="work">${icon('plus')} Новая публикация</button></section>`}
async function home(){await loadProfiles();return `<section class="catalog-hero"><div><p class="eyebrow">ПРОФЕССИОНАЛЫ КРАСОТЫ</p><h1>Мастера, чьи работы<br><em>хочется сохранить.</em></h1><p>Открывайте портфолио, находите свой стиль и записывайтесь в пару касаний.</p></div><div class="catalog-hero-actions"><a class="button" href="/inspiration" data-route>Смотреть вдохновение ${icon('arrow')}</a><span>Запись доступна без регистрации</span></div></section><section class="discovery"><div class="section-heading catalog-heading"><div><p class="eyebrow">НАЙТИ СВОЕГО МАСТЕРА</p><h2>Выбирайте по работам, а не обещаниям.</h2></div><span class="muted">${profiles.length?profiles.length+' мастера':'Новая история красоты'}</span></div>${filters()}<div id="results">${profileResults()}</div></section><section class="invitation"><div class="invitation-copy"><p class="eyebrow">ВАШЕ ЛИЧНОЕ ПРОСТРАНСТВО</p><h2>Ваш талант.<br>Ваша <em>история.</em></h2><p>Публикуйте работы, собирайте свою аудиторию и принимайте заявки в одном красивом пространстве.</p><button class="button light" data-action="create">Открыть студию ${icon('arrow')}</button><span class="invitation-note">Бесплатно на старте · Для мастеров по всей России</span></div><div class="preview-card" aria-label="Пример оформления страницы"><span class="sample-tag">ВИТРИНА МАСТЕРА</span><div class="preview-avatar">a</div><h3>Ваше имя</h3><p>Красота — в деталях</p><div class="preview-line"></div><div class="preview-service"><span>Новая работа</span><span>✧</span></div><div class="preview-service"><span>Запись по ссылке</span><span>→</span></div><span class="preview-cta">Открыть страницу ${icon('arrow')}</span></div></section>`}
function profileForm(p={}){return `<form data-form="profile"><div class="form-grid">${field('Имя / название студии','name',p.name,'text','required maxlength="80"')}${field('Город','city',p.city,'text','required maxlength="80" placeholder="Например, Новосибирск"')}${field('Адрес страницы','slug',p.slug||me?.login?.replaceAll('_','-'),'text','required pattern="[a-z0-9][a-z0-9-]{2,39}" maxlength="40"')}<label class="field">Направление<select name="category">${categories.slice(1).map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label></div><label class="field">О себе<textarea name="bio" rows="3" maxlength="1500" placeholder="Ваш подход, опыт и то, что вы любите в своей работе">${esc(p.bio)}</textarea></label>${field('Место приёма (публикуется на странице)','address',p.address,'text','maxlength="200" placeholder="Студия, район или адрес"')}<fieldset class="theme-picker"><legend>Оформление страницы</legend>${[['cream','Кремовое'],['wine','Винное'],['green','Изумрудное']].map(([v,l])=>`<label class="theme-option ${v}"><input type="radio" name="theme" value="${v}" ${(p.theme||'cream')===v?'checked':''}><span>${l}</span></label>`).join('')}</fieldset><details class="location-details"><summary>Показывать на карте</summary><p class="hint">Необязательно. Укажите координаты студии. Для приёма дома лучше выбрать приблизительную точку: координаты будут публичными.</p><div class="form-grid">${field('Широта','latitude',p.latitude??'','number','step="any" min="-90" max="90"')}${field('Долгота','longitude',p.longitude??'','number','step="any" min="-180" max="180"')}</div><button type="button" class="text-button" data-action="locate">Использовать моё местоположение</button></details><label class="check-field"><input name="published" type="checkbox" ${p.published?'checked':''}> Опубликовать страницу в каталоге</label><p class="form-error" role="alert"></p><button class="button" type="submit">Сохранить страницу ${icon('check')}</button></form>`}
async function studioPage(){if(!me)return `<section class="page-intro"><div><p class="eyebrow">ДЛЯ ТЕХ, КТО СОЗДАЁТ КРАСОТУ</p><h1>Ваша личная <em>студия.</em></h1></div></section><section class="onboarding"><div class="onboarding-art"><span class="big-a">a</span><p>Место для вашего таланта</p></div><div><h2>Всё начинается с вас</h2><p class="muted">Портфолио, услуги и календарь. Создайте аккаунт мастера и соберите страницу за несколько минут.</p><button class="button" data-action="auth-mode" data-mode="register" data-account="master">Я мастер — создать студию ${icon('arrow')}</button><button class="text-button" data-action="auth">Уже есть аккаунт</button></div></section>`;if(me.account_type!=='master')return `<section class="page-intro"><div><p class="eyebrow">АККАУНТ КЛИЕНТА</p><h1>Ваша роль — <em>клиент.</em></h1></div></section>${empty('Студия доступна мастерам','Тип кабинета выбирается при регистрации. В вашем аккаунте доступны сохранённые работы, подписки, записи и отзывы.','<a class="button" href="/me" data-route>Открыть «Моё»</a>')}`;[studio,appointments]=await Promise.all([api('/studio'),api('/appointments')]);if(!studio.profile)return `<section class="page-intro"><div><p class="eyebrow">ПЕРВОЕ ЗНАКОМСТВО</p><h1>Расскажите <em>о себе.</em></h1></div></section><section class="panel narrow">${profileForm()}</section>`;const p=studio.profile;return `<section class="page-intro" style="margin-bottom: 20px; flex-direction: row; flex-wrap: wrap; align-items: center; gap: 20px; justify-content: space-between;"><div style="display: flex; align-items: center; gap: 15px;"><div class="avatar big">${p.avatar?`<img src="${esc(p.avatar)}" alt="Ваше фото">`:esc(p.name[0])}</div><div><p class="eyebrow" style="margin-bottom: 2px;">МОЯ СТУДИЯ</p><h1 style="font-size: 1.5rem; margin: 0 0 4px;">Здравствуйте, <em>${esc(p.name.split(' ')[0])}.</em></h1><span class="status-label" style="margin: 0;">${p.published?'Страница опубликована':'Страница скрыта'}</span></div></div><div class="action-row"><button class="button secondary" data-action="share" data-slug="${esc(p.slug)}">${icon('share')} Поделиться</button><a class="button" href="/m/${esc(p.slug)}" data-route>Моя страница ${icon('arrow')}</a></div></section><div class="top-controls"><div class="studio-actions compact-actions"><button class="button secondary" data-action="avatar">Изменить фото</button><button class="button secondary" data-action="edit-profile">${icon('settings')} Настройки страницы</button><button class="button secondary" data-action="push">${icon('bell')} Уведомления</button><button class="button secondary" data-action="install">Приложение</button><button class="button secondary" data-action="logout">Выйти</button></div></div>${creatorBoard(studio.profile)}${studioBookings()}${availabilityManager()}<div class="studio-layout"><div style="grid-column: 1 / -1;"><section class="panel"><div class="section-heading"><h2>Мои работы <span class="count">${studio.works.length}</span></h2><button class="button small" data-action="work">${icon('plus')} Добавить работу</button></div>${studio.works.length?`<div class="works-grid">${studio.works.map((w,i)=>media.studioTile(w,i,studio.works)).join('')}</div>`:empty('Покажите, что вы создаёте','Добавьте любимые работы. Фотографии сами расскажут о вашем стиле.')}</section><section class="panel"><div class="section-heading"><h2>Услуги и цены</h2><button class="text-button" data-action="service">${icon('plus')} Добавить</button></div>${serviceList(studio.services,true)}</section></div></div>`}
function serviceList(list,editable=false,master=''){return list.length?`<div class="service-list">${list.map(s=>`<div class="service-row"><div><h3>${esc(s.name)}</h3><span class="muted">${s.duration} мин</span></div><strong>${money(s.price)}</strong>${editable?`<button class="icon-button" data-action="delete-service" data-id="${s.id}" aria-label="Удалить услугу">${icon('close')}</button>`:`<button class="button secondary small" data-action="book" data-master="${master}" data-service="${s.id}">Записаться</button>`}</div>`).join('')}</div>`:'<p class="muted">Услуги пока не добавлены.</p>'}
async function masterPage(slug){const p=await api('/profiles/'+encodeURIComponent(slug));window.currentMaster=p;document.title=p.name+' — Ателье';if(profileCalendarSlug!==slug){profileCalendarSlug=slug;profileCalendarMonth=new Date();profileCalendarDate='';if(p.availability?.length){const first=new Date(masterDateKey(p.availability[0].start)+'T12:00:00');profileCalendarMonth=new Date(first.getFullYear(),first.getMonth(),1);profileCalendarDate=dayKey(first)}}const own=me?.id===p.user_id;return `<a href="/" data-route class="back-link">← Все мастера</a><section class="profile-cover ${esc(p.theme)}"><span class="eyebrow">${esc(p.category)} / ${esc(p.city)}</span><span class="cover-monogram">a</span></section><section class="profile-intro"><div class="avatar extra-big">${p.avatar?`<img src="${esc(p.avatar)}" alt="${esc(p.name)}">`:esc(p.name[0])}</div><div class="profile-title"><div><h1>${esc(p.name)}</h1><p>${icon('pin')} ${esc(p.city)}${p.address?' · '+esc(p.address):''}</p></div><div class="action-row">${!own&&p.services.length?`<button class="button" data-action="book" data-master="${p.user_id}" data-service="${p.services[0]?.id||''}">${me?'Выбрать время':'Записаться без регистрации'} ${icon('arrow')}</button>`:''}${own?'':`<button class="button secondary ${p.following?'selected-action':''}" data-action="follow" data-master="${p.user_id}" data-following="${p.following?'1':'0'}">${icon('heart')}${p.following?'Вы подписаны':'Подписаться'}</button>`}<button class="button secondary" data-action="share" data-url="/m/${esc(p.slug)}">${icon('share')} Поделиться</button></div></div>${!p.published?'<p class="notice">Страница скрыта. Её видите только вы — опубликуйте её в настройках.</p>':''}<p class="bio">${esc(p.bio)}</p></section><div class="profile-content"><section><div class="section-heading"><h2>Портфолио</h2><span class="muted">${p.works.length} работ</span></div>${p.works.length?`<div class="works-grid public-works">${p.works.map(w=>`<figure class="work-tile"><a class="image-button" href="/w/${w.id}" data-route><img src="${esc(w.image)}" alt="${esc(w.caption||'Работа мастера')}" loading="lazy">${media.badges(w)}<span class="work-open">Открыть работу ${icon('arrow')}</span></a><figcaption>${esc(w.caption)}${w.service_name?`<small>${esc(w.service_name)} · ${money(w.service_price)}</small>`:''}</figcaption></figure>`).join('')}</div>`:empty('Здесь скоро появятся работы','Мастер ещё оформляет своё портфолио.')}</section><aside class="panel services-panel"><p class="eyebrow">ВРЕМЯ ДЛЯ СЕБЯ</p><h2>Услуги и запись</h2>${!me&&!p.is_demo?'<p class="hint">Можно записаться без регистрации — нужны только имя и контакт.</p>':''}${p.is_demo?'<p class="muted">Это пример оформления. Для записи выберите действующего мастера.</p><a class="button secondary" href="/book" data-route>Найти мастера для записи ${icon("arrow")}</a>':serviceList(p.services,false,p.user_id)}<p class="hint">Запись по запросу. Мастер подтвердит время в приложении.</p></aside></div>${p.reviews.length?`<section class="profile-reviews"><div class="section-heading"><h2>Отзывы <span class="count">${p.review_count}</span></h2><strong class="rating-total">★ ${p.rating}</strong></div><div class="review-grid">${p.reviews.map(r=>`<article class="review-card"><div class="review-stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><p>${esc(r.text||'Клиент оценил визит без комментария.')}</p><small>Подтверждённый визит · ${esc(r.service)}</small></article>`).join('')}</div></section>`:''}`}
function profileHighlights(p){const labels=['Работы','Новые','Детали','Процесс','Отзывы','Обо мне'];return p.works.length?`<section class="profile-highlights" aria-label="Подборки мастера">${p.works.slice(0,6).map((w,i)=>`<a href="/w/${w.id}" data-route><span><img src="${esc(w.image)}" alt="${esc(w.caption||labels[i])}" loading="lazy"></span><small>${labels[i]}</small></a>`).join('')}</section>`:''}
function dayKey(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function masterLocal(value){return new Date(Number(value)+(window.currentMaster?.schedule?.utc_offset??-new Date().getTimezoneOffset())*60000)}
function masterDateKey(value){return masterLocal(value).toISOString().slice(0,10)}
function masterTime(value){return masterLocal(value).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'})}
function updateProfileCalendar(){const p=window.currentMaster,node=$('#profile-calendar');if(!p||!node)return;const y=window.scrollY;node.outerHTML=requestCalendar(p.availability||[],p,me?.id===p.user_id);const next=$('#profile-calendar');if(!matchMedia('(prefers-reduced-motion: reduce)').matches)next.animate([{opacity:.45,transform:'translateY(3px)'},{opacity:1,transform:'translateY(0)'}],{duration:160,easing:'ease-out'});window.scrollTo({top:y,behavior:'instant'})}
function slotLabel(slot){const d=masterLocal(slot.start);return d.toLocaleDateString('ru-RU',{weekday:'short',day:'numeric',month:'long',timeZone:'UTC'})+' · '+masterTime(slot.start)}
function requestCalendar(slots=[],p={},own=false){
 const today=new Date(masterDateKey(Date.now())+'T12:00:00'),first=new Date(profileCalendarMonth.getFullYear(),profileCalendarMonth.getMonth(),1);
 const days=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(),start=(first.getDay()+6)%7;
 const title=first.toLocaleDateString('ru-RU',{month:'long',year:'numeric'});
 const monthSlots=slots.filter(s=>{const d=masterLocal(s.start);return d.getUTCFullYear()===first.getFullYear()&&d.getUTCMonth()===first.getMonth()});
 const marked=new Set(monthSlots.map(s=>masterDateKey(s.start)));
 const selected=profileCalendarDate||dayKey(today);
 const selectedSlots=slots.filter(s=>masterDateKey(s.start)===selected);
 const selectedLabel=new Date(selected+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'});
 const cells=Array.from({length:start},()=>'<i></i>').join('')+Array.from({length:days},(_,i)=>{const day=i+1,key=dayKey(new Date(first.getFullYear(),first.getMonth(),day));return `<button type="button" class="${key===dayKey(today)?'today ':''}${key===selected?'selected-day ':''}${marked.has(key)?'available-day':''}" data-action="profile-date" data-date="${key}">${day}${marked.has(key)?'<b></b>':''}</button>`}).join('');
 const times=selectedSlots.length?selectedSlots.map(slot=>{const service=p.services.find(s=>s.duration*60000<=slot.end-slot.start);return `<div class="calendar-slot"><span>${masterTime(slot.start)}</span>${own?'<small>Свободно</small>':service?`<button type="button" class="text-button" data-action="book" data-master="${p.user_id}" data-start="${slot.start}" data-slot="${slot.id}" data-end="${slot.end}">Свободно, записаться ${icon('arrow')}</button>`:'<small>Окно короче услуг</small>'}</div>`}).join(''):'<p class="muted">В этот день свободных окон нет.</p>';
 return `<div class="request-calendar" id="profile-calendar" aria-label="Календарь свободного времени"><div class="request-calendar-head"><strong>${title}</strong><span class="calendar-nav"><button type="button" data-action="profile-month" data-delta="-1" aria-label="Предыдущий месяц">‹</button><button type="button" data-action="profile-month" data-delta="1" aria-label="Следующий месяц">›</button></span></div><div class="request-weekdays"><span>Пн</span><span>Вт</span><span>Ср</span><span>Чт</span><span>Пт</span><span>Сб</span><span>Вс</span></div><div class="request-days">${cells}</div><div class="selected-day-slots"><strong>${selectedLabel}</strong>${times}</div></div>`;
}
function availabilityPreview(p,own){const slots=p.availability||[],next=slots.find(slot=>p.services.some(s=>s.duration*60000<=slot.end-slot.start))||slots[0],service=next&&p.services.find(s=>s.duration*60000<=next.end-next.start);if(next)return `<section class="next-slot"><div class="next-slot-head"><h2>Ближайшее окно</h2>${icon('calendar')}</div><div class="next-slot-time"><span>${icon('clock')}</span><div><strong>${esc(slotLabel(next))}</strong><small>${service?esc(service.name)+' · '+service.duration+' мин':'Свободное время'}</small></div></div>${!own&&service?`<button class="button full" data-action="book" data-master="${p.user_id}" data-service="${service.id}" data-start="${next.start}" data-slot="${next.id}" data-end="${next.end}">Записаться на это время ${icon('arrow')}</button>`:''}<a class="text-button slot-link" href="#profile-calendar">Посмотреть все доступные слоты ${icon('arrow')}</a></section>`;return own?`<section class="next-slot empty-slot"><h2>Ближайшее окно</h2><p>На ближайшие дни всё занято.</p><button class="button secondary full" data-action="availability">Настроить график ${icon('settings')}</button></section>`:`<section class="next-slot empty-slot"><h2>Ближайшее окно</h2><p>На ближайшие дни всё занято. Выберите другую дату.</p></section>`}
function profileBookingPanel(p,own){const slots=p.availability||[];return `<aside class="profile-booking-card" id="profile-services"><div class="booking-calendar-section"><p class="eyebrow">РАСПИСАНИЕ</p><h2>Календарь</h2>${availabilityPreview(p,own)}${requestCalendar(slots,p,own)}<p class="hint">Выберите свободное время. Заявки и записи автоматически занимают место в календаре.</p></div><div class="booking-services-section" style="margin-top: 30px; border-top: 1px dashed #e3d9ca; padding-top: 30px;"><p class="eyebrow">ВРЕМЯ ДЛЯ СЕБЯ</p><h2>Услуги</h2>${serviceList(p.services,false,p.user_id)}</div></aside>`}
async function masterConceptPage(slug){const p=await api('/profiles/'+encodeURIComponent(slug));window.currentMaster=p;document.title=p.name+' — Ателье';if(profileCalendarSlug!==slug){profileCalendarSlug=slug;profileCalendarMonth=new Date();profileCalendarDate='';if(p.availability?.length){const first=new Date(masterDateKey(p.availability[0].start)+'T12:00:00');profileCalendarMonth=new Date(first.getFullYear(),first.getMonth(),1);profileCalendarDate=dayKey(first)}}const own=me?.id===p.user_id;return `<a href="/" data-route class="back-link">← Все мастера</a><article class="master-showcase ${esc(p.theme)}"><section class="master-showcase-hero"><div class="master-portrait">${p.avatar?`<img src="${esc(p.avatar)}" alt="${esc(p.name)}">`:esc(p.name[0])}</div><div class="master-showcase-copy"><p class="eyebrow">${esc(p.category)} · ${esc(p.city)}</p><h1>${esc(p.name)}</h1><p class="master-showcase-bio">${esc(p.bio||'Красота — в деталях и внимании к каждому образу.')}</p><div class="master-metrics"><div><strong>${p.works.length}</strong><span>работ</span></div><div><strong>${p.rating?`★ ${p.rating}`:'—'}</strong><span>рейтинг</span></div><div><strong>${p.review_count||0}</strong><span>отзывов</span></div></div></div><div class="master-showcase-actions">${!own&&p.services.length?`<button class="button" data-action="book" data-master="${p.user_id}" data-service="${p.services[0]?.id||''}">${me?'Выбрать время':'Записаться'}${icon('arrow')}</button>`:''}${own?'':`<button class="button secondary ${p.following?'selected-action':''}" data-action="follow" data-master="${p.user_id}" data-following="${p.following?'1':'0'}">${icon('heart')} ${p.following?'Вы подписаны':'Подписаться'}</button>`}<button class="icon-button master-share" data-action="share" data-url="/m/${esc(p.slug)}" aria-label="Поделиться страницей">${icon('share')}</button></div></section>${!p.published?'<p class="notice">Страница скрыта. Её видите только вы — опубликуйте её в настройках.</p>':''}</article><div class="showcase-layout"><section class="showcase-portfolio">${profileHighlights(p)}<nav class="showcase-tabs" aria-label="Разделы страницы"><button data-action="swipe-tab" data-index="0" class="active">Портфолио</button><button data-action="swipe-tab" data-index="1">Календарь</button><button data-action="swipe-tab" data-index="2">Услуги</button><button data-action="swipe-tab" data-index="3">О мастере</button>${p.reviews.length?'<button data-action="swipe-tab" data-index="4">Отзывы</button>':''}</nav></section><div class="swipeable-screens"><div class="swipe-screen active" data-index="0"><div class="section-heading" id="portfolio"><h2>Портфолио</h2></div>${p.works.length?`<div class="showcase-works ${p.works.length===1?'single-work':''}">${p.works.map(w=>`<figure><a href="/w/${w.id}" data-route><img src="${esc(w.image)}" alt="${esc(w.caption||'Работа мастера')}" loading="lazy"><span>${esc(w.caption||w.service_name||'Открыть работу')} ${icon('arrow')}</span></a></figure>`).join('')}</div>`:empty('Здесь скоро появятся работы','Мастер ещё оформляет своё портфолио.')}</div><div class="swipe-screen" data-index="1"><div class="section-heading"><h2>Календарь</h2></div><div class="panel booking-calendar-panel">${availabilityPreview(p,own)}${requestCalendar(p.availability||[],p,own)}</div></div><div class="swipe-screen" data-index="2"><div class="section-heading"><h2>Услуги</h2></div><div class="panel booking-services-panel">${serviceList(p.services,false,p.user_id)}</div></div><div class="swipe-screen" data-index="3"><div class="section-heading"><h2>О мастере</h2></div><p class="about-master" id="about-master">${icon('pin')} ${esc(p.city)}${p.address?' · '+esc(p.address):''}</p><p style="font-size: 0.95rem; line-height: 1.6; color: #665c52;">${esc(p.bio||'')}</p></div>${p.reviews.length?`<div class="swipe-screen" data-index="4"><section class="profile-reviews showcase-reviews" id="profile-reviews"><div class="section-heading"><h2>Отзывы <span class="count">${p.review_count}</span></h2><strong class="rating-total">★ ${p.rating}</strong></div><div class="review-grid">${p.reviews.map(r=>`<article class="review-card"><div class="review-stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><p>${esc(r.text||'Клиент оценил визит без комментария.')}</p><small>Подтверждённый визит · ${esc(r.service)}</small></article>`).join('')}</div></section></div>`:''}</div></div>`}
function visitCard(a){return `<article class="visit-card"><div class="visit-date"><strong>${new Date(a.start).toLocaleDateString('ru-RU',{day:'numeric',month:'short'})}</strong><span>${timeLabel(a.start)}</span></div><div><span class="status-label">${statusLabels[a.status]}</span><h3><a href="/m/${esc(a.slug)}" data-route>${esc(a.master_name||'Мастер')}</a></h3><p>${esc(a.service)} · ${money(a.price)}</p>${a.review_id?`<p class="review-stars">${'★'.repeat(a.review_rating)}${'☆'.repeat(5-a.review_rating)} <small>Отзыв опубликован</small></p>`:''}</div>${a.status==='done'&&!a.review_id?`<button class="button secondary small" data-action="review" data-id="${a.id}" data-master="${esc(a.master_name)}">Оставить отзыв</button>`:''}</article>`}
function clientSettings(){return `<section class="panel account-panel"><div><p class="eyebrow">МОЙ АККАУНТ</p><h2>Настройки</h2><p class="muted">Аккаунт клиента: ${esc(me.login)}</p></div><div class="account-actions"><button class="button secondary" data-action="push">${icon('bell')} Уведомления</button><button class="button secondary" data-action="account-settings">Настройки аккаунта ${icon('settings')}</button><button class="text-button danger-button" data-action="logout">Выйти из аккаунта</button></div></section>`}
async function clientPage(){if(!me)return `<section class="page-intro"><div><p class="eyebrow">ВАШЕ ПРОСТРАНСТВО</p><h1>Красота, которую вы <em>выбрали.</em></h1></div></section>${empty('Соберите своё Ателье','Войдите как клиент, чтобы сохранять работы, подписываться на мастеров и хранить историю визитов.',`<button class="button" data-action="auth-mode" data-mode="register" data-account="client">Создать аккаунт клиента ${icon('arrow')}</button>`)}`;if(me.account_type!=='client')return studioPage();[library,appointments]=await Promise.all([api('/library'),api('/appointments')]);const upcoming=appointments.filter(a=>['pending','confirmed'].includes(a.status)&&a.start>=Date.now()),history=appointments.filter(a=>a.status==='done'||a.start<Date.now()).reverse();return `<section class="page-intro"><div><p class="eyebrow">ЛИЧНЫЙ КАБИНЕТ КЛИЕНТА</p><h1>Ваше пространство <em>красоты.</em></h1></div><div class="action-row"><a class="button" href="/feed" data-route>Лента моих мастеров ${icon('arrow')}</a><a class="button secondary" href="/calendar" data-route>Все записи</a></div></section>${clientSettings()}<section class="client-section"><div class="section-heading"><h2>Ближайшие записи <span class="count">${upcoming.length}</span></h2></div>${upcoming.length?`<div class="visit-list">${upcoming.map(visitCard).join('')}</div>`:empty('Пока нет будущих визитов','Выберите работу или услугу мастера и отправьте заявку.','<a class="button secondary" href="/" data-route>Найти мастера</a>')}</section><section class="client-section"><div class="section-heading"><h2>История посещений <span class="count">${history.length}</span></h2><span class="muted">Отзывы доступны после завершённого визита</span></div>${history.length?`<div class="visit-list">${history.map(visitCard).join('')}</div>`:empty('История начнётся после первого визита','Завершённые записи и ваши отзывы будут храниться здесь.')}</section><section class="client-section"><div class="section-heading"><h2>Сохранённые работы <span class="count">${library.works.length}</span></h2><span class="muted">Ваши референсы для будущих записей</span></div>${library.works.length?`<div class="saved-grid">${library.works.map(w=>`<article class="saved-card"><a href="/w/${w.id}" data-route><img src="${esc(w.image)}" alt="${esc(w.caption||'Сохранённая работа')}" loading="lazy"><div><span>${esc(w.master_name)} · ${esc(w.city)}</span><h3>${esc(w.caption||w.service_name||'Работа мастера')}</h3>${w.service_name?`<p>${esc(w.service_name)} · ${money(w.service_price)}</p>`:''}</div></a></article>`).join('')}</div>`:empty('Здесь будут ваши идеи','Откройте работу мастера и нажмите «Сохранить».','<a class="button secondary" href="/" data-route>Найти вдохновение</a>')}</section><section class="client-section"><div class="section-heading"><h2>Любимые мастера <span class="count">${library.masters.length}</span></h2></div>${library.masters.length?`<div class="master-grid">${library.masters.map(card).join('')}</div>`:empty('Следите за мастерами','Подпишитесь на мастера, чтобы его страница всегда была под рукой.')}</section>`}
async function workPage(id){const w=await api('/works/'+encodeURIComponent(id));window.currentWork=w;document.title=(w.caption||w.service_name||'Работа')+' — Ателье';const own=me?.id===w.user_id;return `<a href="/m/${esc(w.slug)}" data-route class="back-link">← К странице мастера</a><article class="work-detail"><div class="work-visual">${media.gallery(w)}</div><div class="work-copy"><p class="eyebrow">${w.is_demo?'ПРИМЕР ПУБЛИКАЦИИ':'РАБОТА МАСТЕРА'}</p><a class="work-master" href="/m/${esc(w.slug)}" data-route><div class="avatar">${w.avatar?`<img src="${esc(w.avatar)}" alt="">`:esc(w.master_name[0])}</div><div><strong>${esc(w.master_name)}</strong><span>${esc(w.category)} · ${esc(w.city)}</span></div></a><h1>${esc(w.caption||w.service_name||'Вдохновение для вашего образа')}</h1>${w.service_name?`<div class="work-service"><div><span>Связанная услуга</span><strong>${esc(w.service_name)}</strong><small>${w.service_duration} мин</small></div><b>${money(w.service_price)}</b></div>`:'<p class="muted">Мастер подберёт подходящую услугу при записи.</p>'}<div class="work-actions">${own?'':`<button class="button secondary ${w.saved?'selected-action':''}" data-action="save-work" data-id="${w.id}" data-saved="${w.saved?'1':'0'}">${icon('heart')} ${w.saved?'Сохранено':'Сохранить'}</button>`}<button class="button secondary" data-action="share" data-url="/w/${w.id}">${icon('share')} Поделиться</button></div>${own||w.is_demo?'':`<button class="button full want-same" data-action="book" data-master="${w.user_id}" data-service="${w.service_id||''}" data-work="${w.id}">Хочу так же ${icon('arrow')}</button>`}</div></article>`}
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const datetimeLocal=d=>dateKey(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
const timeLabel=n=>new Date(n).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});
const statusLabels={pending:'Ожидает подтверждения',confirmed:'Подтверждено',cancelled:'Отменено',done:'Завершено'};
async function calendarPage(){if(!me)return guestCalendar();appointments=await api('/appointments');const start=new Date(currentDate);start.setDate(start.getDate()-((start.getDay()+6)%7));const days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return d});const list=appointments.filter(a=>dateKey(new Date(a.start))===dateKey(currentDate));const pending=appointments.filter(a=>a.master_id===me.id&&a.status==='pending');return `<section class="page-intro"><div><p class="eyebrow">МОЙ КАЛЕНДАРЬ</p><h1>Время для <em>красоты.</em></h1></div>${myProfile?'<button class="button" data-action="appointment">'+icon('plus')+' Новая запись</button>':''}</section><section class="calendar-shell"><div class="calendar-toolbar"><h2>${currentDate.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</h2><div class="action-row"><button class="button secondary small" data-action="today">Сегодня</button><button class="icon-button" data-action="week" data-delta="-7" aria-label="Предыдущая неделя">←</button><input class="date-jump" type="date" aria-label="Выбрать дату" id="date-jump" value="${dateKey(currentDate)}"><button class="icon-button" data-action="week" data-delta="7" aria-label="Следующая неделя">→</button></div></div><div class="week-strip">${days.map(d=>`<button class="day ${dateKey(d)===dateKey(currentDate)?'selected':''}" data-action="day" data-date="${dateKey(d)}"><span>${d.toLocaleDateString('ru-RU',{weekday:'short'})}</span><strong>${d.getDate()}</strong><span class="day-mark">${appointments.some(a=>a.status!=='cancelled'&&dateKey(new Date(a.start))===dateKey(d))?'•':' '}</span></button>`).join('')}</div><div class="day-agenda"><div class="section-heading"><h3>${currentDate.toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</h3><span class="muted">Часовой пояс: ${Intl.DateTimeFormat().resolvedOptions().timeZone}</span></div>${list.length?list.map(appointmentCard).join(''):empty('Время для новых планов','На этот день записей пока нет.',myProfile?'<button class="button secondary" data-action="appointment">Добавить запись</button>':'')}</div></section>${pending.length?`<section class="panel"><h2>Заявки на запись <span class="count">${pending.length}</span></h2>${pending.map(appointmentCard).join('')}</section>`:''}`}
function appointmentCard(a){const mine=a.master_id===me.id;return `<article class="appointment ${esc(a.status)}"><div class="appointment-time"><strong>${timeLabel(a.start)}</strong><span>${timeLabel(a.end)}</span></div>${a.reference_image?`<a class="appointment-reference" href="/w/${a.reference_work_id}" data-route><img src="${esc(a.reference_image)}" alt="Референс клиента"></a>`:''}<div class="appointment-info"><span class="status-label">${statusLabels[a.status]}</span><h3>${esc(mine?a.client_name:a.master_name)}</h3><p>${esc(a.service)} · ${money(a.price)}</p>${mine&&a.guest_contact?`<div class="guest-contact"><span>${a.client_id?'Контакт клиента':'Гостевая заявка'}</span><strong>${esc(a.guest_contact)}</strong><small>Контакт указан клиентом, не подтверждён</small>${!a.client_id&&['pending','confirmed'].includes(a.status)?'<small>Подтвердите время по этому контакту — у гостя нет уведомлений.</small>':''}</div>`:''}<p class="hint">${new Date(a.start).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}${a.reference_caption?' · Хочет работу «'+esc(a.reference_caption)+'»':''}${a.notes?' · '+esc(a.notes):''}</p>${a.review_id?`<p class="review-stars">${'★'.repeat(a.review_rating)}${'☆'.repeat(5-a.review_rating)} <small>Ваш отзыв</small></p>`:''}</div><div class="appointment-actions">${mine&&a.status==='pending'?`<button class="button small" data-action="appointment-status" data-id="${a.id}" data-status="confirmed">Подтвердить</button>`:''}${mine&&a.status==='confirmed'?`<button class="text-button" data-action="appointment-status" data-id="${a.id}" data-status="done">Завершить</button>`:''}${mine&&['pending','confirmed'].includes(a.status)?`<button class="text-button" data-action="reschedule" data-id="${a.id}">Перенести</button>`:''}${['pending','confirmed'].includes(a.status)?`<button class="text-button" data-action="appointment-status" data-id="${a.id}" data-status="cancelled">Отменить</button>`:''}${!mine&&a.status==='done'&&!a.review_id?`<button class="button secondary small" data-action="review" data-id="${a.id}" data-master="${esc(a.master_name)}">Оставить отзыв</button>`:''}</div></article>`}
async function updateMyCalendar() {
  if (location.pathname !== '/calendar') return render();
  const node = $('.calendar-shell');
  if(!node) return render();
  node.style.opacity = '0.5';
  node.style.pointerEvents = 'none';
  try {
    const content = await calendarPage();
    if ($('#main')) $('#main').innerHTML = content;
  } catch (e) { render(); }
}
async function appointmentDialog(master='',serviceId='',workId='',startAt='',slotId='',slotEnd='') {
  if(!master&&!me){auth();return}
  const booking=Boolean(master&&master!==me?.id);
  let services,reference=null;
  if(booking){
    const info=await api('/masters/'+encodeURIComponent(master)+'/booking');
    
    services=info.services;
    if(workId)reference=await api('/works/'+encodeURIComponent(workId));
  }else{
    studio=await api('/studio');if(!studio.profile){route('/studio');return}services=studio.services;
  }
  const previous=readBookingDraft(),draft=booking&&previous?.master===master&&previous?.work===(workId||'')?previous:null;
  const date=startAt?new Date(Number(startAt)):new Date(currentDate);if(!startAt)date.setHours(Math.max(9,new Date().getHours()+1),0,0,0);
  const chosen=(slotId?serviceId:'')||draft?.values?.service_id||serviceId;
  dialog(booking?'Запрос на запись':'Новая запись',
    (reference?'<div class="booking-reference"><img src="'+esc(reference.image)+'" alt="Референс"><span>Референс прикреплён к заявке</span></div>':'')+
    '<p class="muted">'+(booking?'Выберите желаемое время. Мастер подтвердит его или предложит другое.':'Услуга подставит стоимость и длительность. Телефон клиента не нужен.')+'</p>'+(!me?'<p class="hint">Регистрация не нужна. Оставьте контакт, чтобы мастер мог подтвердить время.</p>':'')+
    '<form data-form="appointment" data-master="'+esc(master)+'" data-work="'+esc(workId)+'" data-slot-start="'+esc(startAt)+'">'+(slotId?'<input type="hidden" name="availability_slot_id" value="'+esc(slotId)+'">':'')+
    field(booking?'Ваше имя':'Имя клиента','client_name',draft?.values?.client_name||'','text','required maxlength="100" list="recent-clients" autocomplete="name"')+
    (!me?field('Телефон или Telegram','contact',draft?.values?.contact||'','text','required maxlength="100" placeholder="+7 999 123-45-67 или @username" autocomplete="off"')+'<p class="hint">Контакт увидит мастер. Номер не нужно подтверждать, SMS не отправляем.</p><div class="booking-trap" aria-hidden="true"><label>Ваш сайт<input name="website" tabindex="-1" autocomplete="off"></label></div>':'')+
    '<datalist id="recent-clients">'+[...new Set(appointments.filter(a=>a.master_id===me?.id).map(a=>a.client_name))].map(n=>'<option value="'+esc(n)+'">').join('')+'</datalist>'+
    '<label class="field">Услуга<select aria-label="Услуга" name="service_id" '+(booking?'required':'')+'><option value="">Выберите услугу</option>'+services.map(s=>{const fits=!slotEnd||(s.duration*60000<=Number(slotEnd)-Number(startAt));return '<option value="'+s.id+'" '+(chosen===s.id?'selected':'')+(fits?'':' disabled')+'>'+esc(s.name)+' · '+money(s.price)+' · '+s.duration+' мин'+(fits?'':' (мало времени)')+'</option>'}).join('')+'</select></label>'+
    field('Дата и время','date',startAt?datetimeLocal(date):draft?.values?.date||datetimeLocal(date),'datetime-local','required')+
    (!booking? `<div class="form-grid manual-fields" style="${chosen?'display:none':''}"><div style="display:contents">${field('Длительность, мин (своя)','duration',60,'number', 'min="5" max="720" ' + (chosen?'disabled':'required'))}</div><div style="display:contents">${field('Цена, ₽ (своя)','price',0,'number', 'min="0" max="1000000" ' + (chosen?'disabled':'required'))}</div></div>` : '')+
    '<label class="field">Комментарий<textarea aria-label="Комментарий" name="notes" maxlength="1000" rows="2" placeholder="Необязательно">'+esc(draft?.values?.notes||'')+'</textarea></label><p class="form-error" role="alert"></p>' + (booking ? `<button type="submit" class="slide-to-confirm"><div class="slide-track"><span>Отправить заявку</span></div><div class="slide-thumb">${icon('arrow')}</div></button>` : `<button class="button full" type="submit">Сохранить запись ${icon('check')}</button>`) + ''+(!me?'<button class="text-button full" type="button" data-action="booking-login">У меня есть аккаунт — войти</button>':'')+'</form>');
  if(booking)captureBookingDraft($('form[data-form=appointment]',modal));
}
async function mapPage(){await loadProfiles();return `<section class="page-intro"><div><p class="eyebrow">КРАСОТА РЯДОМ</p><h1>Мастера <em>на карте.</em></h1></div><button class="button secondary" data-action="map-locate">${icon('pin')} Рядом со мной</button></section>${filters()}<div class="map-layout"><div id="map" aria-label="Карта мастеров"></div><aside class="map-results">${profiles.filter(p=>p.latitude!==null).length?profiles.filter(p=>p.latitude!==null).map(card).join(''):empty('Первые точки ещё впереди','Здесь появятся мастера, которые добавят своё место приёма.')}</aside></div><p class="hint">На карте показаны только мастера с указанным местоположением. Адреса добавляют сами мастера.</p>`}
async function mountMap(){if(!window.L){await new Promise((resolve,reject)=>{const link=document.createElement('link');link.rel='stylesheet';link.href='/vendor/leaflet.css';document.head.append(link);const script=document.createElement('script');script.src='/vendor/leaflet.js';script.onload=resolve;script.onerror=reject;document.head.append(script)})}if(!$('#map'))return;mapInstance=L.map('map',{scrollWheelZoom:false}).setView([55.75,60],3);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).addTo(mapInstance);const points=profiles.filter(p=>p.latitude!==null);for(const p of points){const marker=L.circleMarker([p.latitude,p.longitude],{radius:10,color:'#fff',weight:3,fillColor:'#a92349',fillOpacity:1}).addTo(mapInstance);const el=document.createElement('div');const link=document.createElement('a');link.textContent=p.name;link.href='/m/'+p.slug;link.dataset.route='';el.append(link);marker.bindPopup(el)}if(points.length)mapInstance.fitBounds(points.map(p=>[p.latitude,p.longitude]),{padding:[40,40],maxZoom:13})}
function scheduleClock(minutes){return String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0')}
function availabilityManager(){const c=studio.schedule;if(!c)return `<section class="panel availability-manager"><h2>Календарь временно недоступен</h2><p class="hint">Обновите страницу через несколько секунд.</p></section>`;return `<section class="panel availability-manager"><div class="section-heading"><div><p class="eyebrow">ВАШ РАБОЧИЙ ГРАФИК</p><h2>Календарь готов к записи</h2></div><button class="button small" data-action="availability">${icon('settings')} Настроить график</button></div><p class="hint">Свободное время доступно автоматически. Добавляйте записи в календарь — занятые часы исчезнут с вашей страницы. Отмена записи снова освобождает время.</p><p>${scheduleClock(c.opening)}–${scheduleClock(c.closing)} · UTC+${c.utc_offset/60} · ${c.weekdays.length} дней в неделю</p><a class="text-button" href="/calendar" data-route>Открыть календарь ${icon('arrow')}</a></section>`}
async function availabilityDialog(){if(!me||me.account_type!=='master')return;const data=studio?.schedule?studio:await api('/studio'),c=data.schedule;if(!c){toast('Календарь временно недоступен. Обновите страницу.');return}dialog('Рабочий график',`<form data-form="schedule"><p class="hint">Все часы внутри графика свободны, пока их не займёт заявка или запись.</p><div class="form-grid">${field('Начало дня','opening',scheduleClock(c.opening),'time','required')}${field('Конец дня','closing',scheduleClock(c.closing),'time','required')}</div><label class="field">Часовой пояс<select name="utc_offset">${Array.from({length:11},(_,i)=>i+2).map(h=>`<option value="${h*60}" ${c.utc_offset===h*60?'selected':''}>UTC+${h}</option>`).join('')}</select></label><fieldset class="schedule-weekdays"><legend>Рабочие дни</legend>${['Вс','Пн','Вт','Ср','Чт','Пт','Сб'].map((label,d)=>`<label><input type="checkbox" name="weekday" value="${d}" ${c.weekdays.includes(d)?'checked':''}>${label}</label>`).join('')}</fieldset><p class="form-error" role="alert"></p><button class="button full" type="submit">Сохранить график</button></form>`)}

let scrollObserver=null;
function initScrollSpy(){
  if(scrollObserver){scrollObserver.disconnect();scrollObserver=null}
  const sections=document.querySelectorAll('.showcase-portfolio > *[id], .showcase-reviews[id]');
  const tabs=document.querySelectorAll('.showcase-tabs a');
  if(!sections.length||!tabs.length)return;
  scrollObserver=new IntersectionObserver(entries=>{
    entries.forEach(e=>{
      if(e.isIntersecting){
        tabs.forEach(t=>{
          const active=t.getAttribute('href')==='#'+e.target.id;
          if(active&&!t.classList.contains('active')&&navigator.vibrate)navigator.vibrate(5);
          t.classList.toggle('active',active);
        });
      }
    });
  },{rootMargin:'-10% 0px -80% 0px'});
  sections.forEach(s=>scrollObserver.observe(s));
}
async function render(){const id=++renderId;if(mapInstance){mapInstance.remove();mapInstance=null}document.title='Ателье — пространство мастеров';const previousMain=$('#main');previousMain?.setAttribute('aria-busy','true');try{const p=location.pathname;const content=p==='/book'?await bookingPage():p==='/studio'?await studioPage():p==='/calendar'?await calendarPage():p==='/map'?await mapPage():p==='/me'?await clientPage():p==='/feed'?await feedPage():p==='/inspiration'?await inspirationPage():p==='/visit'?await guest.page():p.startsWith('/m/')?await masterConceptPage(p.slice(3)):p.startsWith('/w/')?await workPage(p.slice(3)):await home();if(id!==renderId)return;const commit=()=>{if(id!==renderId)return;app.innerHTML=header()+`<main id="main">${!navigator.onLine?'<p class="notice">Вы офлайн. Для просмотра актуальных записей подключитесь к интернету.</p>':''}${content}</main>`+footer()+nav();initScrollSpy();};if(previousMain&&document.visibilityState==='visible'&&document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){await document.startViewTransition(commit).updateCallbackDone}else commit();if(p==='/map')await mountMap()}catch(e){if(id===renderId){if(!$('#main'))app.innerHTML=header()+'<main id="main"></main>'+nav();$('#main').removeAttribute('aria-busy');$('#main').innerHTML=empty('Не получилось открыть страницу',esc(e.message),'<button class="button" data-action="retry">Попробовать ещё раз</button>')}}}
