document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const button=form.querySelector('button[type=submit],button:not([type])'),error=form.querySelector('.form-error');if(button)button.disabled=true;if(error)error.textContent='';try{const data=Object.fromEntries(new FormData(form));if(form.dataset.form==='auth'){const result=await post('/auth/'+form.dataset.mode,data);await refreshMe();const returnTo=form.dataset.return==='/'?accountPath():form.dataset.return||accountPath();const pending=readBookingDraft();await route(pending?.authPending?pending.returnTo:returnTo);if(result.recovery){resumeAfterRecovery=Boolean(pending?.authPending);recoveryDialog(result.recovery)}else{modal.close();if(pending?.authPending)await resumeBooking()}}else if(form.dataset.form==='password'){if(data.new_password!==data.confirm_password)throw Error('Новые пароли не совпадают');await post('/account/password',data,'PUT');modal.close();toast('Пароль изменён')}else if(form.dataset.form==='profile'){data.published=form.elements.published.checked;await post('/profile',data,'PUT');await refreshMe();modal.close();await render();toast('Страница сохранена')}else if(form.dataset.form==='service'){await post('/services',data);modal.close();await render();toast('Услуга добавлена')}else if(form.dataset.form==='publication'){await api('/works'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PUT':'POST',body:media.formData(form)});media.disposeEditor();modal.close();await render();toast('Работа сохранена')}else if(['work','avatar'].includes(form.dataset.form)){await api(form.dataset.form==='work'?'/works':'/avatar',{method:'POST',body:new FormData(form)});modal.close();await refreshMe();await render();toast('Фото сохранено')}else if(form.dataset.form==='schedule'){const minutes=v=>{const [h,m]=v.split(':').map(Number);return h*60+m};await post('/schedule',{opening:minutes(data.opening),closing:minutes(data.closing),utc_offset:Number(data.utc_offset),weekdays:new FormData(form).getAll('weekday').map(Number)},'PUT');modal.close();await render();toast('График сохранён')}else if(form.dataset.form==='appointment'){if(!me){captureBookingDraft(form);const draft=readBookingDraft();if(!draft)throw Error('Откройте форму записи заново');const result=await post('/guest-appointments',{...data,start:new Date(data.date).getTime(),master_id:form.dataset.master,reference_work_id:form.dataset.work||undefined,access_key:draft.accessKey});clearBookingDraft();modal.close();await route(result.manage_path);toast('Заявка отправлена. Сохраните личную ссылку.');return}const start=new Date(data.date).getTime();await post('/appointments',{...data,start,master_id:form.dataset.master||undefined,reference_work_id:form.dataset.work||undefined});clearBookingDraft();modal.close();currentDate=new Date(start);route('/calendar');toast(form.dataset.master?'Заявка отправлена мастеру':'Запись добавлена')}else if(form.dataset.form==='reschedule'){await post('/appointments/'+form.dataset.id,{start:new Date(data.date).getTime()},'PATCH');modal.close();render();toast('Запись перенесена')}else if(form.dataset.form==='review'){await post('/appointments/'+form.dataset.id+'/review',data);modal.close();await render();toast('Отзыв опубликован')}}catch(err){if(error)error.textContent=err.message;else toast(err.message)}finally{if(button)button.disabled=false}});
document.addEventListener('change',e=>{if(e.target.matches('form[data-form=appointment] [name=date]')){const form=e.target.form,slot=form.querySelector('[name=availability_slot_id]');if(slot&&new Date(e.target.value).getTime()!==Number(form.dataset.slotStart))slot.remove()}if(e.target.id==='date-jump'){currentDate=new Date(e.target.value+'T12:00');render()}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&['search','city'].includes(e.target.id)){search=$('#search').value;city=$('#city').value;render()}});
window.addEventListener('popstate',render);window.addEventListener('hashchange',()=>{if(location.pathname==='/visit')render()});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('online',()=>{toast('Соединение восстановлено');render()});window.addEventListener('offline',()=>toast('Нет соединения. Новые изменения пока нельзя сохранить.'));
