async function feedPage(){
  if(!me)return '<section class="page-intro"><div><p class="eyebrow">ВДОХНОВЕНИЕ РЯДОМ</p><h1>Ваши <em>мастера.</em></h1></div></section>'+empty('Лента ваших подписок','Войдите, чтобы видеть новые работы любимых мастеров.','<button class="button" data-action="auth">Войти</button>');
  const feed=await api('/feed');feedCursor=feed.next;
  return '<section class="page-intro"><div><p class="eyebrow">НОВОЕ У ТЕХ, КОГО ВЫ ВЫБРАЛИ</p><h1>Мои <em>мастера.</em></h1></div><a class="button secondary" href="/" data-route>Найти мастера '+icon('arrow')+'</a></section><div class="feed-layout"><aside class="feed-note"><span class="eyebrow">ВАША ЛИЧНАЯ ПОДБОРКА</span><h2>У каждого образа<br>есть <em>своя история.</em></h2><p>Работы мастеров, на которых вы подписаны. Сохраняйте идеи и находите вдохновение для следующего визита.</p><a href="/me" data-route class="text-button">Сохранённые работы '+icon('arrow')+'</a></aside><section class="feed-column" aria-label="Лента работ"><div id="feed-items">'+(feed.items.length?feed.items.map(media.feedCard).join(''):empty(feed.following?'Новые работы ещё впереди':'Выберите своих мастеров',feed.following?'Ваши мастера ещё не опубликовали работы. Они появятся здесь после публикации.':'Подпишитесь на мастера на его странице — здесь будут появляться его работы.','<a class="button" href="/" data-route>Посмотреть мастеров '+icon('arrow')+'</a>'))+'</div><button class="button secondary full" data-action="feed-more" '+(feedCursor?'':'hidden')+'>Показать ещё</button></section></div>';
}
async function inspirationPage(){
  const query=new URLSearchParams({category,city});
  const feed=await api('/inspiration?'+query);feedCursor=feed.next;
  return `<section class="inspiration-hero"><div><p class="eyebrow">ОТ МАСТЕРОВ СО ВСЕЙ РОССИИ</p><h1>Красота — это<br><em>повод вдохновиться.</em></h1><p>Свежие работы, техники и идеи. Сохраняйте то, к чему хочется вернуться.</p></div><a class="button secondary" href="/" data-route>Найти мастера ${icon('arrow')}</a></section><section class="inspiration-toolbar">${filters()}<div class="section-heading"><div><p class="eyebrow">СВЕЖИЕ ПУБЛИКАЦИИ</p><h2>Вдохновение</h2></div><span class="muted">Новые работы появляются здесь первыми</span></div></section><section class="inspiration-grid" id="inspiration-items" aria-label="Лента вдохновения">${feed.items.length?feed.items.map(media.inspirationCard).join(''):empty('Здесь скоро станет красиво','Первые публикации мастеров появятся после оформления портфолио.')}</section><button class="button secondary inspiration-more" data-action="feed-more" data-source="inspiration" ${(feedCursor&&feed.items.length)?'':'hidden'}>Показать ещё ${icon('arrow')}</button>`;
}
function captureBookingDraft(form,authPending=false){
  if(!form?.dataset.master||form.dataset.master===me?.id)return;
  const values=Object.fromEntries(new FormData(form));
  const previous=readBookingDraft(),same=previous?.master===form.dataset.master&&previous?.work===(form.dataset.work||'');
  const accessKey=same&&previous.accessKey?previous.accessKey:Array.from(crypto.getRandomValues(new Uint8Array(32)),v=>v.toString(16).padStart(2,'0')).join('');
  saveBookingDraft({master:form.dataset.master,work:form.dataset.work||'',values,returnTo:location.pathname,authPending,accessKey});
}
async function resumeBooking(){
  const draft=readBookingDraft();if(!draft||!me)return;
  try{await appointmentDialog(draft.master,draft.values.service_id,draft.work,draft.values.date?new Date(draft.values.date).getTime():'',draft.values.availability_slot_id||'')}catch(e){toast(e.message)}
}
modal.addEventListener('close',()=>{media.disposeEditor();if(resumeAfterRecovery){resumeAfterRecovery=false;void resumeBooking()}});
document.addEventListener('input',e=>{const form=e.target.closest('form[data-form=appointment]');if(form)captureBookingDraft(form)});
document.addEventListener('change',e=>{
  const form=e.target.closest('form[data-form=appointment]');if(form)captureBookingDraft(form);
  if(e.target.matches('form[data-form=publication] input[type=file]'))try{media.addPhotos(e.target);$('.form-error',e.target.form).textContent=''}catch(err){$('.form-error',e.target.form).textContent=err.message}
});
document.addEventListener('scroll',e=>{
  if(!e.target.classList?.contains('photo-track'))return;
  const count=e.target.parentElement.querySelector('.gallery-count');
  if(count)count.textContent=(Math.round(e.target.scrollLeft/e.target.clientWidth)+1)+' / '+e.target.children.length;
},true);

await refreshMe().catch(()=>{});await render();if(me&&readBookingDraft()?.authPending)await resumeBooking();

// Returning from a guest booking tab should reveal new requests in the master's cabinet.
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&me?.account_type==='master'&&['/studio','/calendar'].includes(location.pathname)&&!modal.open)render()});

let activeSlider=null,sliderStartX=0,sliderCurrentX=0;
document.addEventListener('pointerdown',e=>{
  const s=e.target.closest('.slide-to-confirm');
  if(s&&!s.classList.contains('confirmed')){
    activeSlider=s;sliderStartX=e.clientX;s.style.cursor='grabbing';
    if(navigator.vibrate)navigator.vibrate(10)
  }
});
document.addEventListener('pointermove',e=>{
  if(!activeSlider)return;
  sliderCurrentX=Math.max(0,e.clientX-sliderStartX);
  const maxS=activeSlider.offsetWidth-54;
  if(sliderCurrentX>maxS)sliderCurrentX=maxS;
  const thumb=activeSlider.querySelector('.slide-thumb');
  const track=activeSlider.querySelector('.slide-track');
  thumb.style.transform=`translateX(${sliderCurrentX}px)`;
  track.style.opacity=1-(sliderCurrentX/maxS);
});
document.addEventListener('pointerup',e=>{
  if(!activeSlider)return;
  const maxS=activeSlider.offsetWidth-54;
  const thumb=activeSlider.querySelector('.slide-thumb');
  const track=activeSlider.querySelector('.slide-track');
  if(sliderCurrentX>=maxS*0.95){
    thumb.style.transform=`translateX(${maxS}px)`;
    if(navigator.vibrate)navigator.vibrate([15,50,15]);
    const form=activeSlider.closest('form');
    if(form){
      if(form.checkValidity()){
        activeSlider.classList.add('confirmed');
        form.dispatchEvent(new Event('submit',{cancelable:true,bubbles:true}))
      }else{
        form.reportValidity();
        thumb.style.transition='transform 0.3s cubic-bezier(0.175,0.885,0.32,1.275)';
        thumb.style.transform=`translateX(0px)`;
        track.style.opacity=1;
        setTimeout(()=>thumb.style.transition='',300)
      }
    }
  }else{
    if(navigator.vibrate&&sliderCurrentX>10)navigator.vibrate(10);
    thumb.style.transition='transform 0.3s cubic-bezier(0.175,0.885,0.32,1.275)';
    thumb.style.transform=`translateX(0px)`;
    track.style.opacity=1;
    setTimeout(()=>thumb.style.transition='',300)
  }
  activeSlider.style.cursor='grab';
  activeSlider=null;
});


  document.addEventListener('click', e => {
    const btn = e.target.closest('button[data-action="swipe-tab"]');
    if(btn) {
      const idx = btn.dataset.index;
      const screens = document.querySelector('.swipeable-screens');
      if(screens) {
        const target = screens.querySelector('.swipe-screen[data-index="'+idx+'"]');
        if(window.innerWidth > 700) {
          screens.querySelectorAll('.swipe-screen').forEach(s => s.classList.remove('active'));
          if(target) target.classList.add('active');
        } else {
          if(target) target.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'start' });
        }
      }
      btn.parentElement.querySelectorAll('button').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    }
  });

  // Sync scroll with tabs
  let scrollTimeout;
  document.addEventListener('scroll', e => {
    if(e.target.classList && e.target.classList.contains('swipeable-screens')) {
      clearTimeout(scrollTimeout);
      scrollTimeout = setTimeout(() => {
        const screens = e.target;
        const scrollLeft = screens.scrollLeft;
        const width = screens.clientWidth;
        const idx = Math.round(scrollLeft / width);
        const tabs = document.querySelectorAll('.showcase-tabs button[data-action="swipe-tab"]');
        if(tabs[idx]) {
          tabs.forEach(b => b.classList.remove('active'));
          tabs[idx].classList.add('active');
        }
      }, 50);
    }
  }, {capture: true});
